def traceOnLimit : Carrier f →L[ℂ] ℂ :=
  (DirectLimit.Module.lift ℂ ι A f τ hcompat).mkContinuous 1
    (DirectLimit.induction f fun i x => by simpa only [one_mul] using hbound i x)

